# Incremental Result Streamer demo: fan-out simulation with early cancel.
import time, itertools
def shard(name,items,delay):
    for it in items:
        yield {"shard":name,"item":it}
def stream(sources,limit=4):
    gens=[shard(n,its,d) for n,its,d in sources]
    seen=set(); n=0
    for g in itertools.zip_longest(*gens):
        for r in g:
            if r is None: continue
            if r["item"] in seen: continue
            seen.add(r["item"]); n+=1
            yield r
            if n>=limit: return
srcs=[("s1",["a","b","c"],0.01),("s2",["b","d","e"],0.02),("s3",["f"],0.01)]
for r in stream(srcs): print(r)
print("cancelled after 4 unique results; remaining work freed")

